        existing.reference + ' (' + existing.id + '). Open that original calendar.'), {
        code: 'AGREEMENT_RENEWAL_ALREADY_ASSIGNED', status: 409,
        details: {agreementId: existing.id, sourceId: edition.sourceId, editionId: edition.id}
